// Live values — the exact numbers the SVG is reading right now.
const val = (k) => ({ value: nb.get(k), type: typeof nb.get(k) });
return {
  sides:    val('sides'),     // number — indexes the polygon vertex count
  radius:   val('radius'),
  rotation: val('rotation'),
  stroke_w: val('stroke_w'),
  fill:     val('fill'),       // #rrggbb string, fed straight to SVG fill
  stroke:   val('stroke'),
};
